import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';
import AuthPage from './pages/Auth';
import Layout from './components/Layout';
import Dashboard from './pages/Dashboard';
import Chatbot from './pages/Chatbot';
import Profs from './pages/Profs';
import Profile from './pages/Profile';
import Admin from './pages/Admin';
import ProfDashboard from './pages/ProfDashboard';

function PrivateRoute({ children, roles }) {
  const { user, loading } = useAuth();
  if (loading) return <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100vh', background: '#0a0a0f', color: '#6c63ff', fontSize: '1.2rem' }}>⏳ Chargement...</div>;
  if (!user) return <Navigate to="/login" replace />;
  if (roles && !roles.includes(user.role)) return <Navigate to="/" replace />;
  return children;
}

function AppRoutes() {
  const { user } = useAuth();

  return (
    <Routes>
      <Route path="/login" element={user ? <Navigate to="/" replace /> : <AuthPage />} />

      <Route path="/" element={<PrivateRoute><Layout /></PrivateRoute>}>
        <Route index element={
          user?.role === 'admin'     ? <Navigate to="/admin"  replace /> :
          user?.role === 'professeur'? <Navigate to="/prof"   replace /> :
          <Dashboard />
        } />
        <Route path="chatbot"    element={<PrivateRoute roles={['étudiant']}><Chatbot /></PrivateRoute>} />
        <Route path="profs"      element={<PrivateRoute><Profs /></PrivateRoute>} />
        <Route path="profil"     element={<PrivateRoute><Profile /></PrivateRoute>} />
        <Route path="admin"      element={<PrivateRoute roles={['admin']}><Admin /></PrivateRoute>} />
        <Route path="prof"       element={<PrivateRoute roles={['professeur']}><ProfDashboard /></PrivateRoute>} />
      </Route>

      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
}

export default function App() {
  return (
    <AuthProvider>
      <BrowserRouter>
        <AppRoutes />
      </BrowserRouter>
    </AuthProvider>
  );
}
